const $=id=>document.getElementById(id);
function time(seconds){const total=Math.max(0,Math.floor(seconds||0));return `${String(Math.floor(total/3600)).padStart(2,'0')}:${String(Math.floor(total%3600/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`;}
function date(value){try{return new Intl.DateTimeFormat('uk-UA',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Kyiv'}).format(new Date(value));}catch{return '—';}}
async function load(){const status=$('analytics-status');status.textContent='Оновлюємо дані…';$('analytics-refresh').disabled=true;try{const response=await fetch('/api/analytics/summary',{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw new Error();const data=await response.json();$('metric-viewers').textContent=data.totalViewers||0;$('metric-watch').textContent=time(data.totalWatchSeconds);$('metric-recordings').textContent=data.recordingViewers||0;$('metric-questions').textContent=data.totalQuestions||0;$('metric-cta').textContent=data.totalCtaClicks||0;const body=$('analytics-viewers');body.replaceChildren();for(const viewer of data.viewers||[]){const row=document.createElement('tr');const identity=document.createElement('td');const strong=document.createElement('strong'),small=document.createElement('small');strong.textContent=viewer.name;small.textContent=viewer.username?`@${viewer.username}`:`ID ${viewer.telegramId}`;identity.append(strong,small);for(const value of [identity,time(viewer.watchSeconds),viewer.lastSlide||'—',viewer.recordings?.length||0,viewer.questions||0,viewer.ctaClicks||0,date(viewer.lastSeenAt)]){const cell=value instanceof HTMLElement?value:document.createElement('td');if(!(value instanceof HTMLElement))cell.textContent=String(value);row.append(cell);}body.append(row);}$('analytics-empty').hidden=!!data.viewers?.length;$('analytics-export').hidden=!data.configured;status.textContent=data.configured?`Оновлено: ${date(new Date())}`:'Supabase ще не підключено. Інтерфейс готовий до тесту після створення бази.';}catch{status.textContent='Не вдалося завантажити аналітику.';}finally{$('analytics-refresh').disabled=false;}}
$('analytics-refresh').addEventListener('click',load);load();
